"""
Research sub page: Evolutionary Algorithms (research-ea.html) — part 4 of the article series (MDE, AI4SE, Digital Twins).
What evolutionary / genetic algorithms are, where they sit next to "modern" AI, how each operation works, and how to
try them. Imported by build.py; figures in ea_figs.py (data from the seeded runs in ea_sim.py), behaviour in
assets/ea.js, styles in assets/ea.css.

Chapter 02 teaches every step on one running example, the two-hills landscape (a candidate is a point, its fitness the
height); chapter 03 holds the family, evolution in software engineering, and two case studies from my own work: the
wind-farm layout of my master's thesis [Net17] and the hybrid-car controller [NWN+15].
"""
import math

from ai4se import T, cite, definition, curious
from ea_figs import (REFS, r, fig_map, demo_pipes, demo_loop, fig_encodings, fig_chromosomes, demo_wake, demo_selection,
                     demo_crossover, demo_mutation, demo_converge, fig_family, demo_phev, fig_phev_tradeoff, fig_runtimes,
                     demo_encoding, demo_onestep, hero_ea, STARTER_RES, HILLS)
import article_common
import ea_sim as sim

NL = "\n"
FILE = "research-ea.html"
OWN = ["Net17", "NWN+15"]          # GJN+15a was never cited, so it was never listed

# the hook in the intro: 12 turbines on 100 cells
LAYOUTS = math.comb(100, 12)
YEARS = LAYOUTS / 1e6 / (3600 * 24 * 365)
assert round(LAYOUTS / 1e15, 2) == 1.05 and round(YEARS) == 33

# the starter at the end: how many of the 10 seeds reach the high hill?
S_HIGH = [s for s, f, _ in STARTER_RES if f >= .99]
S_LOW = [s for s, f, _ in STARTER_RES if f < .99]
S_EVALS = STARTER_RES[0][2]
# random search vs the balanced setting on the two hills (ea_figs.demo_converge): runs that reached the top (≥ 0.99)
R_TOP, B_TOP = (sum(sim.hills(*r[-1][0]) >= .99 for r in HILLS[k]["runs"]) for k in ("random", "balanced"))
assert HILLS["random"]["high"] == 10 and R_TOP < B_TOP
assert len(S_LOW) == 3 and all(abs(f - .6) < .001 for s, f, _ in STARTER_RES if s in S_LOW) and S_EVALS == 1100
# the budget sentence in #fitness: 20 + 60 × (20 − 2 elite) evaluations; at one minute each
assert 20 + 60 * 18 == S_EVALS and round(S_EVALS / 60) == 18
# the hills: heights quoted in the text
assert abs(sim.hills(*sim.LOW) - .6) < 1e-9 and abs(sim.hills(*sim.HIGH) - 1) < 1e-9


def _seeds(lst, lang):
    words = [str(s) for s in lst]
    return (", ".join(words[:-1]) + (" and " if lang == "en" else " und ") + words[-1]) if len(words) > 1 else words[0]


