    return (f'<figure class="media art-fig"><div class="tbl-wrap"><table class="tbl mono ea-cheat">{head}{body}</table></div>'
            f'<figcaption class="mono">{L(T("<b>One loop, many names.</b> Where the knobs of chapter 02 sit in three Python libraries (as of October 2026; check the docs of your version).", "<b>Eine Schleife, viele Namen.</b> Wo die Regler aus Kapitel 02 in drei Python-Bibliotheken sitzen (Stand Oktober 2026; prüfen Sie die Doku Ihrer Version)."))}</figcaption></figure>')


